import{_ as a,o as t,c as e,ao as i}from"./chunks/framework.CT_nZkbR.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"StrictMode.jl","text":"Loud guarantees for fast Julia","tagline":"Fast by default, and loud the moment you slip off it — not something you discover by profiling.","actions":[{"theme":"brand","text":"Getting Started","link":"/getting_started"},{"theme":"alt","text":"Guarantees","link":"/guarantees"},{"theme":"alt","text":"API Reference","link":"/api"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/el-oso/StrictMode.jl"}]},"features":[{"title":"Ask for the fast path","details":"Say what you want at a call site or a definition — this call must not allocate, this one must stay type-stable — and hear about it the moment it does not hold."},{"title":"Catch the silent traps","details":"Two packages. StrictMode reads inferred types and typed IR, and warns. Add StrictModeTest and AllocCheck, JET and TrimCheck prove the same properties and fail your build. Boxing and quietly allocating loops stop being invisible."},{"title":"Zero cost when disabled","details":"Checks sit behind a Preferences flag, on by default so dev and test need no setup. Turn it off for a shipped application and each macro compiles to the bare call."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),n={name:"index.md"};function l(o,s,r,h,p,d){return t(),e("div",null,[...s[0]||(s[0]=[i(`<h2 id="Why" tabindex="-1">Why <a class="header-anchor" href="#Why" aria-label="Permalink to &quot;Why {#Why}&quot;">​</a></h2><p>Julia will let your code box a value, miss an inline, drift into a type instability, or allocate in a hot loop — without saying a word. You find out with a profiler, later. StrictMode lets you ask for those properties out loud, and hear about it the moment one breaks.</p><h2 id="Two-packages" tabindex="-1">Two packages <a class="header-anchor" href="#Two-packages" aria-label="Permalink to &quot;Two packages {#Two-packages}&quot;">​</a></h2><p>Know this first — it decides which macro you write.</p><p><strong><a href="./guarantees">StrictMode</a></strong> goes in your <code>Project.toml</code>. It reads inferred types and typed IR and needs no other package. Where it is <strong>guessing</strong> — the allocation and trim checks — it warns instead of failing your build; where it reads the compiled output, it throws.</p><p><strong><a href="./proof_tier">StrictModeTest</a></strong> goes in your <code>test/Project.toml</code>. It brings AllocCheck, JET and TrimCheck, and <strong>gates</strong>: a violation fails CI. Your users never install those backends just to use your package.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>         write @assert_noalloc          write @test_noalloc</span></span>
<span class="line"><span>                  │                             │</span></span>
<span class="line"><span>              StrictMode                  StrictModeTest</span></span>
<span class="line"><span>           reads typed IR                asks AllocCheck</span></span>
<span class="line"><span>                  ↓                             ↓</span></span>
<span class="line"><span>              warns  ⚠                       throws  ✗</span></span>
<span class="line"><span>         while you iterate                   in your tests</span></span></code></pre></div><p>Two macros, different use. One lightweight for interactive develop one rigorous for testing.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@assert_noalloc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> kernel!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, A, B)     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># StrictMode: the scan — warns</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@test_noalloc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   kernel!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(C, A, B)     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># StrictModeTest: AllocCheck&#39;s proof — throws</span></span></code></pre></div><blockquote><p>StrictMode grew out of a JuliaCon 2024 talk, <em>&quot;Why do we need a stricter Julia mode?&quot;</em> The traps that motivated it turned up while tuning a SIMD FFT, where indexing a tuple with a runtime value quietly boxed and cost a measured <strong>135× slowdown</strong> — the kind of thing you only ever find by profiling.</p></blockquote><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> StrictMode</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@assert_noalloc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    sum</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">rand</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># warns if the call looks like it allocates</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@assert_typestable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> muladd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># throws on an inconcrete return type</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@strict</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">            dot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(u, v)              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># the guarantees a hot path wants, together</span></span></code></pre></div><p>From here you can follow <a href="./getting_started">Getting Started</a> for a walkthrough, read through the <a href="./guarantees">Guarantees</a> one by one, or skip to the <a href="./api">API Reference</a>.</p>`,12)])])}const g=a(n,[["render",l]]);export{c as __pageData,g as default};
